(function(){
'use strict';
const E=window.AB01Learning,KEY='ab01_beta02_matrix_session_v1',app=document.getElementById('learning-app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=E.fresh(),storage=true,blockedLoad=false,rawRecord='',notice='',error=false,guide=null,contextView=window.location?.hash==='#applications'?'applications':window.location?.hash==='#start'?'orientation':null;
try{rawRecord=(window.QuidenceStorage||window.localStorage).getItem(KEY)||'';if(rawRecord){const loaded=E.hydrate(JSON.parse(rawRecord));if(loaded)state=loaded;else blockedLoad=true;}}catch{if(rawRecord)blockedLoad=true;else storage=false;}
const el=id=>document.getElementById(id);
function persist(){if(!blockedLoad){try{(window.QuidenceStorage||window.localStorage).setItem(KEY,JSON.stringify(state));}catch{storage=false;}}el('learning-storage').textContent=storage?'Temporary session progress stays in this browser.':'Browser saving is unavailable. Keep this page open to finish and export your report.';}
function log(type,data={}){state.events.push({at:new Date().toISOString(),type,stage:state.stage,...data});}
function task(){return contextView?null:E.TASKS[state.stage]?.[state.index];}
function rec(t){if(!state.records[t.id])state.records[t.id]={taskVersion:t.version,stage:state.stage,status:'draft',draft:{values:['',''],choice:null,explanation:'',otherHelp:false},hint:false,submissions:[],enteredAt:new Date().toISOString()};return state.records[t.id];}
function update(part){const t=task(),r=rec(t);r.draft={...r.draft,...part};r.status='draft';notice=r.submissions.length?'Edited. Submit again to include this version.':'';error=false;log('answer_changed',{taskId:t.id,changes:part});persist();const s=el('answer-status');if(s){s.textContent=notice;s.classList.remove('error');}const next=el('next');if(next)next.disabled=true;const f=el('task-feedback');if(f)f.hidden=true;}
function support(r){return{priorInstruction:!!state.lesson.startedAt||state.priorExposure.some(e=>e.module==='matrix'||e.module==='applications'),systemHint:r.hint,feedbackBeforeThisSubmission:r.submissions.length>0&&state.stage==='practice',otherHelpReported:!!r.draft.otherHelp,moduleOpenedInPhase:state.priorExposure.some(e=>e.stage===state.stage),phase:state.stage,referenceExposurePossible:state.stage==='delayed'&&state.reportReferencePolicy!=='later-reference-hidden-1'};}
function submit(){if(blockedLoad||!task())throw new Error('No active task.');const t=task(),r=rec(t);if(!E.valid(t,r.draft)){notice='Complete the required coordinates and answer choice. A blank coordinate is not zero.';error=true;render();return{ok:false,error:notice};}const answer=structuredClone(r.draft),snapshot={at:new Date().toISOString(),taskVersion:t.version,answer,score:E.score(t,answer),support:support(r)};r.submissions.push(snapshot);r.answer=answer;r.status='submitted';log('answer_submitted',{taskId:t.id,submission:r.submissions.length,support:snapshot.support});notice=state.stage==='practice'?'Answer saved. Read the feedback, then revise or continue.':'Answer saved. Feedback comes after this check.';error=false;persist();render();return{ok:true,taskId:t.id};}
function skip(reason='skipped'){if(!task())return;const t=task(),r=rec(t);r.status=reason;log('task_skipped',{taskId:t.id,reason});persist();advance();}
function showHint(){if(state.stage!=='practice'||!task())throw new Error('Hints are available only in supported practice.');const r=rec(task());r.hint=true;if(r.status==='submitted')r.status='draft';log('hint_viewed',{taskId:task().id});persist();render();}
function enter(stage){contextView=null;setContextHash();state.stage=stage;state.index=0;notice='';error=false;state.phaseStartedAt=state.phaseStartedAt||{};state.phaseStartedAt[stage]=new Date().toISOString();if(stage==='lesson'&&!state.lesson.startedAt)state.lesson.startedAt=new Date().toISOString();log('phase_entered',{phase:stage});persist();render(true);}
function advance(){const t=task(),r=t&&rec(t);if(!t||!['submitted','skipped','not-studied'].includes(r.status)){notice='Submit the answer or skip this task before continuing.';error=true;render();return;}const list=E.TASKS[state.stage];if(state.index<list.length-1){state.index++;notice='';error=false;log('task_opened',{taskId:task().id});persist();render(true);return;}if(state.stage==='pre')enter('lesson');else if(state.stage==='practice')enter('post');else if(state.stage==='post'){state.completedAt=new Date().toISOString();enter('report');}else if(state.stage==='delayed'){state.delayedCompletedAt=new Date().toISOString();enter('report');}}
const stages=[['pre','Before learning'],['lesson','Step-by-step lesson'],['practice','Supported practice'],['post','Fresh tasks'],['report','Evidence report']];
function path(){const current=state.stage==='delayed'?4:stages.findIndex(x=>x[0]===state.stage);return`<nav class="learning-path" aria-label="Learning phases">${stages.map(([id,name],i)=>`<span class="${i===current?'current':i<current?'complete':''}" ${i===current?'aria-current="step"':''}>${i+1} · ${name}</span>`).join('')}</nav>`;}
function matrix(a){return`<div><div class="guide-matrix-title">Matrix A</div><div class="guide-matrix">${a.map((n,i)=>`<span class="${i%2===0?'first':'second'}">${n}</span>`).join('')}</div></div>`;}
const names={pre:'A short starting check.',practice:'Try it with support.',post:'Use the rule in new situations.',delayed:'Return to the idea.'};
const phaseNotes={pre:'Try these before the lesson. You can skip an unfamiliar question or mark a topic as not studied yet. Correctness is shown in the final report.',practice:'You have seen the example. Hints and feedback are available here; their use is recorded separately.',post:'These are new tasks after instruction. No immediate task hints or correctness feedback are provided until this check is finished. Opening the application guide is recorded as additional learning context.',delayed:'This is a later check with different tasks. No immediate system hints or correctness feedback are provided until both tasks are recorded.'};
function render(scroll=false){guide?.dispose();guide=null;if(blockedLoad){app.innerHTML='<div class="card"><h1>Your saved session needs attention.</h1><p>The saved record could not be read. It has been kept unchanged. Download a copy before starting a new session.</p><div class="report-actions"><button id="download-raw" class="btn">Download saved record</button><button id="reset" class="btn primary">Start new session</button></div></div>';el('download-raw').onclick=()=>download('Quidence_Matrix_Unreadable_Record.json',rawRecord,'application/json');el('reset').onclick=resetDialog;return;}if(contextView==='applications'){renderApplications();}else if(contextView==='orientation'||state.stage==='intro'){renderIntroduction();}else if(state.stage==='lesson'){renderLesson();}else if(state.stage==='report'){renderReport();}else renderTask();persist();if(scroll)window.scrollTo?.(0,0);}
function setContextHash(){if(window.history?.replaceState&&window.location)window.history.replaceState(null,'',window.location.pathname+window.location.search+(contextView==='applications'?'#applications':contextView==='orientation'?'#start':''));}
function openContext(view){contextView=view;setContextHash();render(true);}
function renderIntroduction(){
 if(!state.orientationViewedAt){state.orientationViewedAt=new Date().toISOString();log('orientation_viewed',{materialVersion:'0.2-orientation-1'});}
 window.AB01Materials.intro(app,{resuming:state.stage!=='intro',onBegin:()=>{if(state.stage==='intro'){log('starting_check_chosen');enter('pre');}else{contextView=null;setContextHash();render(true);}},onExplore:()=>openContext('applications')});
}
function renderApplications(){window.AB01Materials.applications(app,{onBack:()=>openContext('orientation'),onExposure:details=>{const exposure={at:new Date().toISOString(),module:'applications',stage:state.stage,materialVersion:'0.2-orientation-1',...details};state.priorExposure.push(exposure);log('application_example_viewed',exposure);persist();}});}
if(el('orientation-link'))el('orientation-link').onclick=()=>{if(!blockedLoad)openContext('orientation');};
function renderTask(){const t=task(),r=rec(t),list=E.TASKS[state.stage],a=r.draft;app.innerHTML=`${path()}<div class="topline"><div><span class="eyebrow">Matrix foundations</span><h1>${names[state.stage]}</h1><p class="muted">${phaseNotes[state.stage]}</p></div><button id="reset" class="text-btn">Start a new session</button></div><div class="learning-task"><section class="card task-card"><div class="task-meta"><span class="tag">TASK ${state.index+1} / ${list.length}</span><span>${esc(t.concept)}</span></div><h2>${esc(t.title)}</h2><p>${esc(t.prompt)}</p>${t.matrix?`<div class="learning-matrix-row">${matrix(t.matrix)}${t.vector?`<div class="learning-vector">v = (${t.vector.join(', ')})<br>Find Av</div>`:''}</div>`:''}${t.kind!=='choice'?`<div class="input-row">${t.labels.map((l,i)=>`<div class="field"><label for="answer-${i}">${esc(l)}</label><input id="answer-${i}" data-value="${i}" type="number" step="any" autocomplete="off" placeholder="Enter a number" value="${esc(a.values[i])}"></div>`).join('')}</div>`:''}${t.options?`<div class="choices" role="group" aria-label="Answer choices">${t.options.map((o,i)=>`<button data-choice="${i}" class="choice" aria-pressed="${a.choice===i}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></button>`).join('')}</div>`:''}<section class="explanation-workspace"><h3>Explain your thinking (optional)</h3><p class="review-text" style="margin-top:12px">This explanation is saved for teacher review. It is not automatically scored.</p><p class="review-text">Equations, calculations, or a short explanation are welcome. Your reasoning helps us build a clearer report about what this work shows and what still needs checking. Quidence saves your reasoning for a teacher or tutor to review. A reviewer should judge the mathematics, not grammar, keywords or answer length.</p><label class="sr-only" for="explanation">Explain your thinking</label><textarea id="explanation" placeholder="Show your calculation, formula, or reasoning. A short method is enough.">${esc(a.explanation)}</textarea></section><label class="learning-help-check"><input id="other-help" type="checkbox" ${a.otherHelp?'checked':''}>I used other help for this task. This is recorded as context.</label>${r.hint?`<div class="hint">${esc(t.hint)}</div>`:''}<div class="task-actions"><button id="submit" class="btn primary">Submit answer</button>${state.stage==='practice'?`<button id="hint" class="btn" ${r.hint?'disabled':''}>${r.hint?'Hint viewed':'Show hint'}</button>`:''}<button id="skip" class="text-btn">Skip for now</button>${state.stage==='pre'?'<button id="not-studied" class="text-btn">Not studied yet</button>':''}</div><div id="answer-status" class="learning-answer-status ${error?'error':''}" role="status">${esc(notice||(r.status==='submitted'?'Answer saved.':''))}</div>${state.stage==='practice'&&r.status==='submitted'?`<div id="task-feedback" class="learning-feedback">${Object.values(r.submissions.at(-1).score).every(Boolean)?'Your response matches.':'One or more parts need another look.'} ${esc(t.solution)}<br><span class="review-text">Further revisions follow this feedback and are recorded with that support.</span></div>`:''}</section><div class="learning-progress-actions"><span class="muted" style="font-size:14px">${list.filter(x=>['submitted','skipped','not-studied'].includes(state.records[x.id]?.status)).length} / ${list.length} tasks recorded</span><button id="next" class="btn dark" ${!['submitted','skipped','not-studied'].includes(r.status)?'disabled':''}>${state.index===list.length-1?(state.stage==='pre'?'Open the lesson':state.stage==='practice'?'Start fresh tasks':'View report'):'Next task'}</button></div></div>`;
el('submit').onclick=submit;el('skip').onclick=()=>skip();el('next').onclick=advance;el('reset').onclick=resetDialog;if(el('hint'))el('hint').onclick=showHint;if(el('not-studied'))el('not-studied').onclick=()=>skip('not-studied');document.querySelectorAll('[data-value]').forEach(n=>n.oninput=()=>{const values=[...r.draft.values];values[Number(n.dataset.value)]=n.value===''?'':Number(n.value);update({values});});document.querySelectorAll('[data-choice]').forEach(n=>n.onclick=()=>{update({choice:Number(n.dataset.choice)});render();});el('explanation').oninput=e=>update({explanation:e.target.value});el('other-help').onchange=e=>update({otherHelp:e.target.checked});}
function renderLesson(){const cp=state.lesson.checkpoint,resume=state.lesson.lastStep||0;app.innerHTML=`${path()}<div class="topline"><div><span class="eyebrow">Step-by-step lesson · instructional support</span><h1>Follow every move.</h1><p class="muted">Keep the original counts visible. Pause to predict before the two diagonal moves.</p></div><button id="reset" class="text-btn">Start a new session</button></div>${state.records['pre-1']?.status==='submitted'&&!Object.values(state.records['pre-1'].submissions[0].score).every(Boolean)?'<div class="learning-support">Coordinates may need another look: x describes left/right change, y describes up/down change. Negative means left for x or down for y. The Vector diagnostic is available in the navigation.</div>':''}<section id="guided-workspace" aria-label="Guided matrix transformation"></section><section id="checkpoint-panel" class="lesson-checkpoint" ${!state.lesson.visited.includes(3)?'hidden':''}><span class="eyebrow">Pause and predict · within the lesson</span><h2>What do two new up-steps contribute?</h2><p>The new up-step is (1, 1). Predict the total of two copies before walking the route.</p><div class="input-row"><div class="field"><label for="checkpoint-x">Total rightward change</label><input id="checkpoint-x" data-checkpoint="0" type="number" step="any" value="${esc(cp.values[0])}" placeholder="Your prediction"></div><div class="field"><label for="checkpoint-y">Total upward change</label><input id="checkpoint-y" data-checkpoint="1" type="number" step="any" value="${esc(cp.values[1])}" placeholder="Your prediction"></div></div><div class="report-actions"><button id="checkpoint-submit" class="btn primary">Save prediction</button><button id="checkpoint-hint" class="btn" ${cp.hint?'disabled':''}>Show hint</button></div><div id="checkpoint-hint-text" class="hint" ${cp.hint?'':'hidden'}>Add (1, 1) to another (1, 1). Add the horizontal parts and the vertical parts separately.</div><div id="checkpoint-feedback" class="learning-feedback" ${cp.attempts.length?'':'hidden'}>${cp.attempts.length?checkpointFeedback():''}</div><div id="checkpoint-error" class="learning-answer-status error" role="alert"></div></section><div class="lesson-complete"><p id="lesson-status"></p><button id="lesson-next" class="btn dark" disabled>Continue to supported practice</button></div><div id="matrix-methods" ${state.lesson.visited.includes(6)?'':'hidden'}>${state.lesson.visited.includes(6)?window.QuidenceMatrixMethods?.render()||'':''}</div>`;
function lessonStatus(){const can=state.lesson.visited.length===7&&cp.status==='submitted';el('lesson-next').disabled=!can;el('lesson-status').textContent=`${state.lesson.visited.length} / 7 steps viewed. ${cp.status==='submitted'?'Prediction recorded.':'Record the prediction at Step 4 before continuing.'}`;}
el('reset').onclick=resetDialog;el('checkpoint-submit').onclick=()=>{if(cp.values.some(n=>typeof n!=='number'||!Number.isFinite(n))){el('checkpoint-error').textContent='Enter both coordinates. A blank is not zero.';return;}cp.attempts.push({at:new Date().toISOString(),answer:[...cp.values],correct:cp.values.every(n=>Math.abs(n-2)<.005),support:{lessonExposure:true,hint:cp.hint,priorFeedback:cp.attempts.length>0}});cp.status='submitted';log('lesson_prediction_submitted',{attempt:cp.attempts.length});el('checkpoint-error').textContent='';el('checkpoint-feedback').hidden=false;el('checkpoint-feedback').textContent=checkpointFeedback();persist();guide?.refresh();lessonStatus();};el('checkpoint-hint').onclick=()=>{cp.hint=true;el('checkpoint-hint').disabled=true;el('checkpoint-hint-text').hidden=false;log('lesson_prediction_hint');persist();};document.querySelectorAll('[data-checkpoint]').forEach(n=>n.oninput=()=>{cp.values[Number(n.dataset.checkpoint)]=n.value===''?'':Number(n.value);cp.status='draft';el('checkpoint-feedback').hidden=true;persist();lessonStatus();});el('lesson-next').onclick=()=>{if(state.lesson.visited.length!==7||cp.status!=='submitted')return;state.lesson.completedAt=new Date().toISOString();log('lesson_finished',{stepsVisited:[...state.lesson.visited]});enter('practice');};
guide=window.mountMatrixGuide({canVisitStep:i=>i<=3||cp.attempts.length>0,onStep:i=>{if(!state.lesson.visited.includes(i)){state.lesson.visited.push(i);log('lesson_step_viewed',{step:i});}state.lesson.lastStep=i;if(i>=3)el('checkpoint-panel').hidden=false;if(i===6&&el('matrix-methods')){el('matrix-methods').hidden=false;el('matrix-methods').innerHTML=window.QuidenceMatrixMethods?.render()||'';}persist();lessonStatus();}});if(resume>0)window.MatrixGuide.show(resume);lessonStatus();}
function checkpointFeedback(){const cp=state.lesson.checkpoint,a=cp.attempts.at(-1);return`${a.correct?'Your prediction matches.':'Here is the combination to check.'} Two copies give (1, 1) + (1, 1) = (2, 2): 2 right and 2 up. This is a response during instruction, not an independent baseline.`;}
function supportLabel(s,stage){if(!s)return'No submitted answer';const parts=[stage==='pre'?(s.priorInstruction?'Prior instructional exposure recorded':'Before this lesson'):stage==='practice'?'Supported practice':stage==='post'?'After instruction, no immediate system hint':'Later check, no immediate system hint'];if(stage==='delayed'&&(s.referenceExposurePossible||state.reportReferencePolicy!=='later-reference-hidden-1'))parts.push('prior reference-answer exposure unclear');if(s.systemHint)parts.push('task hint viewed');if(s.feedbackBeforeThisSubmission)parts.push('after task feedback');if(s.otherHelpReported)parts.push('other help reported');if(s.moduleOpenedInPhase)parts.push('learning material or another module opened in this phase');return parts.join(' · ');}
function describe(t,a){if(!a)return'No submitted response';const lines=[];if(t.kind!=='choice')lines.push(`Coordinates: (${a.values.join(', ')})`);if(t.options)lines.push('Choice: '+t.options[a.choice]);return lines.join('\n');}
function matches(s){if(!s)return'No scored response';return Object.entries(s).map(([k,v])=>`${k}: ${v?'matched':'did not match'}`).join('; ');}
function rawReport(){return{...structuredClone(state),learningAdvice:window.AB01Advice.plan(state),phaseEvidence:Object.fromEntries(['pre','practice','post','delayed'].map(s=>[s,E.summarize(state.records,s)])),taskDefinitions:Object.entries(E.TASKS).flatMap(([phase,tasks])=>phase==='delayed'&&!state.delayedCompletedAt?[]:tasks),pendingLaterCheck:{count:state.delayedCompletedAt?0:E.TASKS.delayed.length,referenceSolutionsIncluded:!!state.delayedCompletedAt},interpretationNotes:['Phase-specific observations, not a validated mastery score.','Learning advice uses explicit response-based rules. It is not an exam-grade prediction or an estimate of overall ability.','Pre-check and fresh tasks differ; their outcomes do not establish a causal learning gain.','Parts within one task are related observations, not independent repetitions.','Equations, calculations and diagrams can justify a response without prescribed words. Open reasoning requires human review.','Later-check references are not included until that check is completed. Older reports may have exposed those answers; prior exposure is then uncertain.','System support and self-reported other help are recorded; effort or AI use is not inferred.','Lesson visits record displayed steps, not attention or comprehension.','Orientation explains the activity. Application examples provide instructional exposure; viewing them does not demonstrate understanding.','Browser-local temporary session; no cloud or cross-device student profile.']};}
function phaseCard(stage,title){const items=E.summarize(state.records,stage);return`<section class="learning-stage-report"><span class="eyebrow">${title}</span><h2 style="margin-top:12px">${items.filter(i=>i.status==='submitted').length} / ${items.length} tasks answered</h2><p class="muted">${stage==='pre'?'Starting observations before the guided lesson. Unstudied topics and skips remain missing evidence.':stage==='practice'?'First attempts and final revisions stay distinct. Success following hints or feedback is recorded with that help.':stage==='post'?'New-task observations after instruction. No immediate system hints were available; other help may still be reported.':'Observations from a later session after at least one day.'}</p>${items.map(i=>{const r=state.records[i.id],t=E.TASKS[stage].find(t=>t.id===i.id);return`<div class="learning-task-result"><span class="pill ${i.status==='submitted'&&i.last&&Object.values(i.last).every(Boolean)?'independent':''}">${i.status==='not-studied'?'Not studied yet · missing evidence':i.status==='skipped'?'Skipped · missing evidence':i.status==='submitted'?'Response recorded':'Not checked yet'}</span><h3>${esc(t.concept)}</h3>${i.status==='submitted'?`<p>${esc(matches(i.last))}</p><p class="muted">${esc(supportLabel(i.support,stage))}</p>${r.submissions.length>1?`<p>First submission: ${esc(matches(i.first))}. ${r.submissions.length} submissions retained.</p>`:''}`:'<p class="muted">This does not establish a misconception.</p>'}</div>`;}).join('')}</section>`;}
function coachingPanel(){
 const advice=window.AB01Advice.plan(state),priorities=advice.priorityTargetIds.map(id=>advice.targets.find(t=>t.id===id));
 return `<section class="coaching-panel" aria-label="Suggested learning priorities"><div class="coaching-goal"><span class="eyebrow">This lesson first</span><h2>${esc(advice.goal)}</h2><p>${esc(advice.courseConnection)}</p></div><div class="coaching-priorities">${priorities.map((t,i)=>`<article class="card coaching-priority"><span class="tag">Suggested step ${i+1} · ${esc(t.scope)}</span><h3>${esc(t.name)}</h3><span class="pill">${esc(t.label)}</span><p>${esc(t.why)}</p><p class="coaching-action">${esc(t.action)}</p><details class="coach-evidence"><summary>Which responses led to this suggestion?</summary>${t.evidence.map(e=>`<p>${esc(Object.values(E.TASKS).flat().find(task=>task.id===e.taskId)?.title||'Recorded response')} · ${esc(stages.find(stage=>stage[0]===e.phase)?.[1]||'Later check')} · ${e.matched===null?esc(e.status)+' · missing evidence':e.dimensions.map(d=>esc(d.dimension)+': '+(d.matched?'matched':'did not match')).join('; ')}${e.additionalHelp?' · additional help recorded':''}${e.revisedFromMismatch?' · earlier submission differed':''}</p>`).join('')}</details><details data-coach-review="${t.id}"><summary>Try the suggested practice</summary><p>${esc(t.reminder)}</p><p class="coaching-question">${esc(t.check)}</p><details data-coach-solution="${t.id}"><summary>View the worked self-check</summary><p>${esc(t.solution)}</p></details><p>${esc(t.next)}</p><p class="review-text">${esc(advice.selfCheckNote)}</p></details></article>`).join('')}</div><details class="coaching-all"><summary>See suggestions for all lesson connections</summary>${advice.targets.map(t=>`<div class="coaching-connection"><h3>${esc(t.name)} · ${esc(t.scope)}</h3><p>${esc(t.label)}. ${esc(t.why)}</p><p>${esc(t.action)}</p></div>`).join('')}</details><div class="coaching-next"><h3>After checking these connections</h3><p>${esc(advice.nextDirection)}</p><button id="coach-directions" class="btn">See the wider learning map</button></div></section>`;
}
function attachCoaching(){
 const track=(kind,n)=>n.ontoggle=()=>{if(n.open){log(kind,{targetId:n.dataset.coachReview||n.dataset.coachSolution,adviceVersion:window.AB01Advice.VERSION});persist();}};
 document.querySelectorAll('[data-coach-review]').forEach(n=>track('suggested_practice_opened',n));
 document.querySelectorAll('[data-coach-solution]').forEach(n=>track('suggested_practice_solution_viewed',n));
 el('coach-directions').onclick=()=>openContext('applications');
}
function renderReport(){const delayedStarted=Object.keys(state.records).some(id=>id.startsWith('delay-')),eligible=E.delayEligible(state),when=state.completedAt?new Date(Date.parse(state.completedAt)+86400000).toLocaleString():'';app.innerHTML=`${path()}<div class="learning-report-heading"><div><span class="eyebrow">Your learning record</span><h1>What should I work on next?</h1><p class="muted">Start with two suggested actions for this lesson. Each suggestion shows the recorded responses behind it.</p><p class="learning-session-id">Session ${esc(state.sessionId)}</p></div><div class="report-actions"><button id="export-md" class="btn">Export readable report</button><button id="export-json" class="btn">Export full record</button><button id="reset" class="btn dark">New session</button></div></div>${coachingPanel()}<div class="learning-report-grid">${phaseCard('pre','Before this lesson')}${phaseCard('practice','During supported practice')}${phaseCard('post','Fresh tasks after instruction')}${phaseCard('delayed','Later check')}</div><section class="card learning-review"><h2>The prediction inside the lesson</h2><p>${state.lesson.checkpoint.attempts.length} prediction attempt(s). ${state.lesson.visited.length} steps viewed. The prediction followed lesson content and is kept separate from fresh-task evidence.</p>${state.lesson.checkpoint.attempts.map((a,i)=>`<p class="review-text">Attempt ${i+1}: (${a.answer.join(', ')}) · ${a.correct?'matched':'did not match'} · ${a.support.hint?'hint viewed':'no checkpoint hint'}${a.support.priorFeedback?' · earlier feedback viewed':''}</p>`).join('')}</section><div class="learning-retention"><div><h3>Check again after a delay</h3><p>${state.delayedCompletedAt?'Later check completed: '+esc(new Date(state.delayedCompletedAt).toLocaleString()):eligible?'Two new tasks are available now. Answers from today’s check will stay in the record.':'Available one day after the fresh-task check: '+esc(when)+'. Reopen this page in the same browser, or export your current record.'}</p></div><button id="start-delayed" class="btn primary" ${!eligible||state.delayedCompletedAt?'disabled':''}>${delayedStarted&&!state.delayedCompletedAt?'Resume later check':'Start later check'}</button></div><details><summary>Inspect responses, revisions, support and solutions</summary>${Object.entries(E.TASKS).map(([stage,tasks])=>tasks.map(t=>{const r=state.records[t.id];if(stage==='delayed'&&!state.delayedCompletedAt)return `<article class="record"><h3>Later check · ${esc(t.title)}</h3><p>Not completed. The question and worked explanation stay out of this report until the later check is finished.</p></article>`;return`<article class="record"><span class="tag">${esc(stages.find(x=>x[0]===stage)?.[1]||'Later check')} · Task version ${t.version}</span><h3 style="margin-top:12px">${esc(t.title)}</h3><p>${esc(t.prompt)}</p><p>${esc(r?.status==='submitted'?describe(t,r.answer):r?.status||'Not checked yet')}</p>${r?.answer?.explanation?`<p>Explanation for human review: <span data-no-translate>${esc(r.answer.explanation)}</span></p>`:''}${r?.submissions.map((a,i)=>`<p>Submission ${i+1} · ${esc(a.at)}<br>${esc(describe(t,a.answer))}<br>${esc(matches(a.score))}<br>${esc(supportLabel(a.support,stage))}${a.answer.explanation?'<br>Explanation for review: '+'<span data-no-translate>'+esc(a.answer.explanation)+'</span>':''}</p>`).join('')||''}<p class="feedback">${esc(t.solution)}</p></article>`;}).join('')).join('')}</details><div class="note">These are observations from different tasks and learning conditions. They are not a validated mastery percentage or a causal measure of learning gain. Answers inside one task are related; written explanations need teacher review. Speed, clicks, and step visits do not establish effort or AI use. The record is a temporary browser-local session.</div>`;attachCoaching();el('export-json').onclick=()=>download('Quidence_Matrix_Record.json',JSON.stringify(reportPayload(),null,2),'application/json');el('export-md').onclick=()=>download('Quidence_Matrix_Report.md',window.QuidenceReportTools.markdown('Linear Algebra',reportPayload()),'text/markdown');el('reset').onclick=resetDialog;el('start-delayed').onclick=()=>{if(!E.delayEligible(state)||state.delayedCompletedAt)return;enter('delayed');};if(window.QuidenceReportStore){const saved=window.QuidenceReportStore.save('ab01',{...rawReport(),reportKind:'matrix-learning',markdown:markdown()},state.sessionId);window.QuidenceReportStore.appendNotice(app,saved);}}
function reportPayload(){return window.QuidenceReportStore.prepare('ab01',{...rawReport(),reportKind:'matrix-learning',markdown:markdown()},state.sessionId);}
function markdown(){const lines=['# Linear Algebra Foundations','## Matrix learning record','',`Session: ${state.sessionId}`,`Started: ${state.createdAt}`,`Fresh-task check completed: ${state.completedAt||'not yet'}`,`Later check completed: ${state.delayedCompletedAt||'not yet'}`,''];const advice=window.AB01Advice.plan(state);lines.push('## Suggested next steps',advice.goal,advice.method,'');for(const id of advice.priorityTargetIds){const t=advice.targets.find(t=>t.id===id);lines.push('### '+t.name,t.label,t.why,'Suggested action: '+t.action,'Practice: '+t.check,'Worked self-check: '+t.solution,'Next: '+t.next,'');}lines.push('Next direction: '+advice.nextDirection,advice.courseConnection,advice.selfCheckNote,'');for(const[stage,ts]of Object.entries(E.TASKS)){lines.push('## '+(stages.find(x=>x[0]===stage)?.[1]||'Later check'),'');if(stage==='delayed'&&!state.delayedCompletedAt){lines.push('Two later-check questions remain. Their prompts and worked solutions are withheld until this check is completed.','');continue;}for(const t of ts){const r=state.records[t.id];lines.push(`### ${t.title}`,`Task version: ${t.version}`,t.prompt,r?.status==='submitted'?describe(t,r.answer):r?.status||'Missing evidence','');for(const[i,s]of(r?.submissions||[]).entries())lines.push(`Submission ${i+1}: ${describe(t,s.answer)}`,matches(s.score),supportLabel(s.support,stage),s.answer.explanation?'Explanation (human review):\n'+window.QuidenceReportTools.quote(s.answer.explanation):'No written explanation.','');lines.push('Worked explanation: '+t.solution,'');}}lines.push('## Lesson checkpoint',...state.lesson.checkpoint.attempts.map((a,i)=>`Attempt ${i+1}: (${a.answer.join(', ')}); ${a.correct?'matched':'did not match'}; hint ${a.support.hint?'viewed':'not viewed'}; prior feedback ${a.support.priorFeedback?'viewed':'not viewed'}`),'','## Interpretation limits',...rawReport().interpretationNotes.map(n=>'- '+n));return lines.join('\n');}
function download(name,body,type){if(type==='text/markdown') body=window.QuidenceI18n?.markdown(body)||body;const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function resetDialog(){const d=document.createElement('dialog');d.innerHTML='<h2>Start a new matrix session?</h2><p>Starting over replaces the current matrix session in this browser. Completed reports can be exported before starting over. The vector diagnostic record remain separate.</p><div class="report-actions"><button id="cancel-reset" class="btn">Keep current session</button><button id="confirm-reset" class="btn primary">Start new session</button></div>';document.body.appendChild(d);d.querySelector('#cancel-reset').onclick=()=>{d.close();d.remove();};d.querySelector('#confirm-reset').onclick=()=>{state=E.fresh();contextView=null;setContextHash();blockedLoad=false;notice='';error=false;persist();d.close();d.remove();render(true);};d.addEventListener('cancel',()=>d.remove());d.showModal();}
for(const[id,module]of[['matrix-link','matrix'],['vector-link','vectors']])if(el(id))el(id).onclick=()=>{if(blockedLoad)return;const e={at:new Date().toISOString(),module,stage:state.stage};state.priorExposure.push(e);log('module_opened',{module});persist();};
if(document.modelContext?.registerTool){const tools=[{name:'read_ab01_learning',title:'Read matrix learning session',description:'Read the active phase, task and saved phase-specific observations. Does not reveal active task answers.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(i){if(!i||Object.keys(i).length)throw new Error('Expected an empty object.');return{project:'AB01',version:state.version,phase:state.stage,view:contextView||state.stage,taskId:task()?.id||null,blockedLoad,lessonStepsViewed:[...state.lesson.visited],delayedCheckEligible:E.delayEligible(state),learningAdvice:state.stage==='report'?window.AB01Advice.plan(state):undefined,evidence:Object.fromEntries(['pre','practice','post','delayed'].map(s=>[s,E.summarize(state.records,s).map(r=>state.stage==='report'||s==='practice'?r:{id:r.id,concept:r.concept,status:r.status,feedback:'Available in the report after the check.'})]))};}},{name:'stage_ab01_learning_answer',title:'Stage a matrix learning answer',description:'Fill the active task without submitting or changing phase.',inputSchema:{type:'object',properties:{values:{type:'array',items:{type:'number'},minItems:2,maxItems:2},choice:{type:'integer',minimum:0},explanation:{type:'string'},otherHelp:{type:'boolean'}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(i){const t=task();if(blockedLoad||!t||!i||Object.keys(i).some(k=>!['values','choice','explanation','otherHelp'].includes(k))||i.explanation!==undefined&&typeof i.explanation!=='string'||i.otherHelp!==undefined&&typeof i.otherHelp!=='boolean')throw new Error('Invalid answer input or inactive task.');const draft={...rec(t).draft,...i};if(!E.valid(t,draft))throw new Error('Complete numeric coordinates and a valid choice when required.');update(i);render();return{staged:true,taskId:t.id};}},{name:'submit_ab01_learning_answer',title:'Submit a matrix learning answer',description:'Save the current staged answer with its phase and support conditions. Does not move to the next task.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(i){if(!i||Object.keys(i).length)throw new Error('Expected an empty object.');return submit();}}];for(const t of tools)try{Promise.resolve(document.modelContext.registerTool(t)).catch(()=>{});}catch{}}
render();
})();

